-- 018 (part 0 of 4): step 5 demo re-seed (docs/MavenScout-profiles-membership.md
-- §13 step 5): hiring-manager demo flag and test-data clean-up.
--
-- Run in the Supabase SQL editor after 017, then 018_reseed_demo_1.sql → _4.sql
-- (generated by scripts/demo-seed/build.ts). Safe to re-run: IF NOT EXISTS,
-- idempotent updates and deletes.
--
-- ADDITIVE ONLY for code on main: hiring_managers.is_demo defaults to false.
-- The app sets it on referee one-click accounts created from a demo profile's
-- testimonial (lib/testimonials/referee), which needs this column.
--
-- Storage: SQL can't delete Storage objects. Before running parts 1–4, list
-- the uploads that the test testimonials and videos on demo profiles held
-- (parts 1–4 delete those rows):
--
--   SELECT 'audio-testimonials' AS bucket, audio_path AS path FROM audio_testimonials a
--     JOIN profiles p ON p.id = a.profile_id WHERE p.is_demo AND a.audio_path IS NOT NULL
--       AND a.audio_path NOT LIKE 'demo/%'
--   UNION ALL
--   SELECT 'videos', video_path FROM video_responses v
--     JOIN profiles p ON p.id = v.profile_id WHERE p.is_demo AND v.video_path IS NOT NULL
--       AND v.video_path NOT LIKE 'demo/%';
--
-- `node scripts/demo-seed/media.mjs --clean` removes every object under a demo
-- profile's folder in both buckets (and --upload adds the demo clips under demo/).

DO $check$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'verification_checks')
     OR EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'profiles' AND column_name = 'verification_status') THEN
    RAISE EXCEPTION '018 needs 016 and 017 first';
  END IF;
END $check$;

BEGIN;

-- 1. Demo hiring managers are flagged like demo profiles, so purge_demo.sql
--    can remove them with their openings, notes, shares, reviewer grants,
--    rankings and video requests (all ON DELETE CASCADE).
ALTER TABLE hiring_managers ADD COLUMN IF NOT EXISTS is_demo bool NOT NULL DEFAULT false;

-- The role switcher's demo hiring manager and the two colleague reviewers
-- (003_seed_demo_accounts.sql; ids hardcoded in src/lib/session.tsx).
UPDATE hiring_managers SET is_demo = true
WHERE id IN ('aaaaaaaa-0000-4000-a000-000000000001', 'aaaaaaaa-0000-4000-a000-000000000002', 'aaaaaaaa-0000-4000-a000-000000000003')
  AND NOT is_demo;

-- Referees' one-click accounts made from demo profiles' testimonials.
UPDATE hiring_managers SET is_demo = true
WHERE NOT is_demo
  AND id IN (
    SELECT a.referee_manager_id FROM audio_testimonials a JOIN profiles p ON p.id = a.profile_id
    WHERE p.is_demo AND a.referee_manager_id IS NOT NULL
  );

-- 2. The test account "Dr. Amina Bello" (jsmith@worldbank.org), created by the
--    referee flow while testing; it holds a real-looking World Bank address.
DELETE FROM hiring_managers WHERE id = '97b36e77-0d7d-4bc3-9700-20f0105e36b3';

COMMIT;
